    ap = argparse.ArgumentParser()
    ap.add_argument("--per-step", type=int, default=5, help="agent turns per chosen step")
    ap.add_argument("--agent-max", type=int, default=30)
    ap.add_argument("--mem-max", type=int, default=12)
